import numpy as np

def softmax(scores):
    exp_scores = np.exp(scores)
    return exp_scores / np.sum(exp_scores)

def softmax_stable(scores):
    # meant to be the numerically stable version
    exp_scores = np.exp(scores)
    return exp_scores / np.sum(exp_scores)

