def matmul(A, B):
    # A is (m x n), B is (n x p)
    m, n = len(A), len(A[0])
    n2, p = len(B), len(B[0])
    result = [[0] * p for _ in range(m)]
    for i in range(m):
        for j in range(p):
            for k in range(n):
                result[i][j] += A[i][k] * B[j][k]
    return result

